INSERT INTO entities (type, slug, name, category, attributes, official_stats)
VALUES ('certification', 'fp-3kyu', 'FP技能検定 3級', '金融・保険', '{"short_name":"FP3級","authority":{"name":"日本FP協会","url":"https://www.jafp.or.jp/"},"authority_note":"この検定は日本FP協会と金融財政事情研究会(きんざい)の2団体が並行して実施しており、どちらで受検しても得られる資格は同じ国家検定です。ただし実技試験の内容は団体ごとに違い、合格率も別々に集計されています。試験のしくみの説明と受験手数料は、日本FP協会で受検する場合のものです。","exam":{"eligibility":"FP業務に従事している人、またはこれから従事しようとしている人が対象。","fee_yen":8000,"format":"学科試験と実技試験に分かれており、両方に合格すると3級技能士になる。どちらか一方だけの受検もできる。日本FP協会の学科は60問90分、実技(資産設計提案業務)は20問60分で、いずれも多肢選択式。","questions":null,"duration_minutes":null,"passing_criteria":"学科は60点満点中36点以上。実技(資産設計提案業務)は100点満点中60点以上。いずれも6割が基準になる。","frequency":"CBT(コンピュータ試験)方式で、休止期間を除き、テストセンターの空いている日時から選んで受検できる。休止期間の日程は試験日程のページで公表されている。","result_announcement":"受検日の翌月中旬に合格発表がある。合格発表日の10時から、運営を受託しているCBTソリューションズの受検者ページで試験結果と合格番号を確認できる。合格者には合格発表日に合格証書が普通郵便で発送される。","source_urls":{"eligibility":"https://www.jafp.or.jp/exam/outline/3fp.shtml","fee_yen":"https://www.jafp.or.jp/exam/outline/3fp.shtml","format":"https://www.jafp.or.jp/exam/outline/3fp.shtml","passing_criteria":"https://www.jafp.or.jp/exam/outline/3fp.shtml","frequency":"https://www.jafp.or.jp/exam/schedule/","result_announcement":"https://www.jafp.or.jp/exam/outline/3fp.shtml","fee_yen_kinzai":"https://www.kinzai.or.jp/fp/nittei-fp/45289.html"},"fee_note":"学科と実技を同時に受検する場合が8,000円で、学科のみ・実技のみはそれぞれ4,000円。きんざいで受検する場合も同額。","questions_note":"学科60問・実技20問。ただし実技20問は日本FP協会の値で、きんざいの実技は5題の事例形式である。学科と実技で問題数が違うため1つの数値では記載していない。","duration_note":"学科90分・実技60分(両団体共通)。学科と実技で試験時間が違うため1つの数値では記載していない。","retrieved_at":"2026-07-26"},"related":[{"slug":"fp-2kyu","reason":"上位級。3級に合格すると2級の受検資格が得られる"}],"schedule_url":"https://www.jafp.or.jp/exam/schedule/","verification":{"collected_by":"researcher(一次ソースのみ・2026-07-26)","verified_by":"fact-checker(2026-07-27・2回目。1回目で6件、2回目で7件の不一致を検出)","verified_at":"2026-07-27","result":"🟢 統計は15系列すべて公式表と一致し、合格者数÷受検者数の検算も一致。出典URL全7件の生存を確認。2回目で検出した7件(申込者数の未公表断定・日程URLの誤り・受検資格の推測・受検料の出典不足・出題形式の未確認・伝聞の混入・合算合格率の断定)を修正済み。"},"notes":"🔴 訂正記録(同じ形の誤りを2回続けた): ①当初「きんざいのCBT集計は公式に無い」と書いたが誤り。きんざいは期間別のCBT試験結果を https://www.kinzai.or.jp/ginou/fp/result-fp で公表している。②当初「申込者数は公表されていない」と書いたが誤り。日本FP協会・きんざいとも表に受検申請者数の列があり、きんざいの学科行だけが「‐」だった。どちらも1団体の1ページを見て結論したことが原因である。","public_note":"合格率は日本FP協会ときんざいで別々に集計されており、両団体を合算した3級全体の合格率は、両団体と厚生労働省の公表資料からは確認できませんでした。このページでも合算値は作っていません。学科と実技、さらにきんざいの実技は業務ごとに集計が分かれているため、表を5つに分けています。同じ国家検定でも、どこでどの業務を選んで受けるかによって公表されている合格率は違います。","negative_claims":[{"claim":"学科と実技を合算した3級全体の公式合格率","searched":"日本FP協会の試験結果データ(https://www.jafp.or.jp/exam/syutoku/)、きんざいのCBT試験結果(https://www.kinzai.or.jp/ginou/fp/result-fp)、厚生労働省の技能検定実施状況の報道発表本文と「技のとびら」FP職種ページを確認。職種別の受検申請者数は本文にあるが、職種×等級別の合格率は本文に無く、別添PDFは解析できず未確認。よって「存在しない」ではなく「確認できなかった」と書いている","at":"2026-07-27"},{"claim":"きんざいの学科の受検申請者数","searched":"きんざいのCBT試験結果ページ3期分(49741.html / news-fp/48783.html / 未分類/47014.html)の表を確認。受検申請者数の列自体は存在するが、学科の行は全3期とも「‐」で数値が入っていない。実技は業務ごとに数値が入っており、3級計の行と合算が一致することも検算した","at":"2026-07-27"},{"claim":"日本FP協会ときんざいで学科の合格率が30pt以上違う理由","searched":"両団体のCBT試験結果ページと3級試験要綱(jafp.or.jp/exam/outline/3fp.shtml、kinzai.or.jp/ginou/fp/3kyu/index.html)を確認。出題形式は両団体とも90分60問だが、差の理由についての説明は両団体とも掲載していない。受検者層の内訳(団体受検の比率など)も公表されていない","at":"2026-07-27"}]}', '{"official_stats_blocks":[{"key":"gakka","label":"学科","stats":{"unit":"日本FP協会・CBT・学科試験・期間ごとの集計","series":[{"period":"2025年10月〜2026年2月","applicants":46006,"examinees":42641,"passers":36926,"pass_rate":86.6,"source_url":"https://www.jafp.or.jp/exam/syutoku/","retrieved_at":"2026-07-26"},{"period":"2025年4月〜9月","applicants":46737,"examinees":43335,"passers":37403,"pass_rate":86.31,"source_url":"https://www.jafp.or.jp/exam/syutoku/","retrieved_at":"2026-07-26"},{"period":"2024年10月〜2025年2月","applicants":40652,"examinees":37774,"passers":32274,"pass_rate":85.44,"source_url":"https://www.jafp.or.jp/exam/syutoku/","retrieved_at":"2026-07-26"}],"source_url":"https://www.jafp.or.jp/exam/syutoku/","retrieved_at":"2026-07-26","notes":"CBTは回次ではなく期間で集計されている。期間の長さは一定ではない(直近期は5ヶ月)。受検申請者数・受検者数とも公表されている。全3期について合格者数÷受検者数が公表合格率と一致することを検算済み(丸め差は最大0.01pt)。","unit_labels":{"applicants":"受検申請者数","examinees":"受検者数","passers":"合格者数","pass_rate":"合格率(%)"},"public_note":"日本FP協会で受検した人の学科試験の集計です。実技試験は別の表に分けています。学科と実技を合わせた合格率は公表されていません。"}},{"key":"jitsugi","label":"実技(資産設計提案業務)","stats":{"unit":"日本FP協会・CBT・実技試験(資産設計提案業務)・期間ごとの集計","series":[{"period":"2025年10月〜2026年2月","applicants":46012,"examinees":42409,"passers":35997,"pass_rate":84.88,"source_url":"https://www.jafp.or.jp/exam/syutoku/","retrieved_at":"2026-07-26"},{"period":"2025年4月〜9月","applicants":46705,"examinees":42970,"passers":36687,"pass_rate":85.38,"source_url":"https://www.jafp.or.jp/exam/syutoku/","retrieved_at":"2026-07-26"},{"period":"2024年10月〜2025年2月","applicants":40219,"examinees":37078,"passers":31729,"pass_rate":85.57,"source_url":"https://www.jafp.or.jp/exam/syutoku/","retrieved_at":"2026-07-26"}],"source_url":"https://www.jafp.or.jp/exam/syutoku/","retrieved_at":"2026-07-26","notes":"日本FP協会の実技は「資産設計提案業務」の1種類のみ。きんざいは「個人資産相談業務」など複数の業務から選ぶ形で試験の中身が別物なので、同じ表に混ぜていない。全3期について合格者数÷受検者数が公表合格率と一致することを検算済み。","unit_labels":{"applicants":"受検申請者数","examinees":"受検者数","passers":"合格者数","pass_rate":"合格率(%)"},"public_note":"日本FP協会で受検した人の実技試験(資産設計提案業務)の集計です。きんざいの実技は出題形式が違う別の試験なので、この表には含めていません。"}},{"key":"kinzai-gakka","label":"きんざいの学科","stats":{"unit":"きんざい・CBT・学科試験・期間ごとの集計","series":[{"period":"2025年10月〜2026年2月","applicants":null,"examinees":19510,"passers":10530,"pass_rate":53.97,"source_url":"https://www.kinzai.or.jp/fp/49741.html","retrieved_at":"2026-07-27"},{"period":"2025年4月〜9月","applicants":null,"examinees":21399,"passers":10317,"pass_rate":48.21,"source_url":"https://www.kinzai.or.jp/fp/news-fp/48783.html","retrieved_at":"2026-07-27"},{"period":"2024年10月〜2025年2月","applicants":null,"examinees":18285,"passers":9071,"pass_rate":49.61,"source_url":"https://www.kinzai.or.jp/%E6%9C%AA%E5%88%86%E9%A1%9E/47014.html","retrieved_at":"2026-07-27"}],"source_url":"https://www.kinzai.or.jp/ginou/fp/result-fp","retrieved_at":"2026-07-27","notes":"全3期について合格者数÷受検者数が公表合格率と一致することを検算済み。学科は90分60問で日本FP協会と同じ(https://www.kinzai.or.jp/ginou/fp/3kyu/index.html で確認)。ただし合格率は日本FP協会の80%台に対してこちらは50%前後で、30pt以上の差がある。**この差の理由は両団体とも公表していないため、ここでも書かない。**受検者層の違いなのか問題の違いなのかは、公表資料からは判断できない。2024年10月〜2025年2月の出典URLはきんざいのサイトで「未分類」配下に置かれており、パスに日本語が入る。移動しやすいのでリンク切れ監視の対象にすること。 きんざいは全3期とも学科の受検申請者数を「‐」として掲載していないため applicants は null。実技は掲載されている。","unit_labels":{"applicants":"受検申請者数(きんざいは学科のみ非掲載)","examinees":"受検者数","passers":"合格者数","pass_rate":"合格率(%)"},"public_note":"きんざいで受検した人の学科試験の集計です。学科の試験時間と問題数は日本FP協会と同じですが、合格率は別に集計されています。","source_url_format":"https://www.kinzai.or.jp/ginou/fp/3kyu/index.html"}},{"key":"kinzai-kojin","label":"きんざいの実技(個人資産相談業務)","stats":{"unit":"きんざい・CBT・実技試験(個人資産相談業務)・期間ごとの集計","series":[{"period":"2025年10月〜2026年2月","applicants":6716,"examinees":6195,"passers":4065,"pass_rate":65.61,"source_url":"https://www.kinzai.or.jp/fp/49741.html","retrieved_at":"2026-07-27"},{"period":"2025年4月〜9月","applicants":6049,"examinees":5471,"passers":3561,"pass_rate":65.09,"source_url":"https://www.kinzai.or.jp/fp/news-fp/48783.html","retrieved_at":"2026-07-27"},{"period":"2024年10月〜2025年2月","applicants":6377,"examinees":5771,"passers":3751,"pass_rate":65,"source_url":"https://www.kinzai.or.jp/%E6%9C%AA%E5%88%86%E9%A1%9E/47014.html","retrieved_at":"2026-07-27"}],"source_url":"https://www.kinzai.or.jp/ginou/fp/result-fp","retrieved_at":"2026-07-27","notes":"きんざいの実技は受検時にどの業務で受けるかを選ぶ。業務ごとに合格率が違うので、合算せず業務ごとに表を分けている。検算: 2期は公表合格率と一致。2025年10月〜2026年2月のみ自己計算65.62%に対し公表65.61%で0.01ptの差があり、端数処理の違いとみられる。**公表値をそのまま載せている。**","unit_labels":{"applicants":"受検申請者数","examinees":"受検者数","passers":"合格者数","pass_rate":"合格率(%)"},"public_note":"きんざいの実技試験のうち「個人資産相談業務」を選んだ人の集計です。"}},{"key":"kinzai-hoken","label":"きんざいの実技(保険顧客資産相談業務)","stats":{"unit":"きんざい・CBT・実技試験(保険顧客資産相談業務)・期間ごとの集計","series":[{"period":"2025年10月〜2026年2月","applicants":14051,"examinees":12719,"passers":6093,"pass_rate":47.9,"source_url":"https://www.kinzai.or.jp/fp/49741.html","retrieved_at":"2026-07-27"},{"period":"2025年4月〜9月","applicants":16425,"examinees":14632,"passers":6445,"pass_rate":44.05,"source_url":"https://www.kinzai.or.jp/fp/news-fp/48783.html","retrieved_at":"2026-07-27"},{"period":"2024年10月〜2025年2月","applicants":12557,"examinees":10992,"passers":5140,"pass_rate":46.76,"source_url":"https://www.kinzai.or.jp/%E6%9C%AA%E5%88%86%E9%A1%9E/47014.html","retrieved_at":"2026-07-27"}],"source_url":"https://www.kinzai.or.jp/ginou/fp/result-fp","retrieved_at":"2026-07-27","notes":"全3期について合格者数÷受検者数が公表合格率と一致することを検算済み。同じきんざいの実技でも、個人資産相談業務が3期とも65%前後なのに対しこちらは44〜48%で、20pt前後低い。どちらを選ぶかで数字が変わるという事実は受検前に知る価値がある。**ただし理由は公表されていないため書かない。**","unit_labels":{"applicants":"受検申請者数","examinees":"受検者数","passers":"合格者数","pass_rate":"合格率(%)"},"public_note":"きんざいの実技試験のうち「保険顧客資産相談業務」を選んだ人の集計です。同じきんざいの実技でも、選んだ業務によって合格率は違います。"}}]}')
